import functools

def retry(*, tries=3, exceptions=(Exception,)):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_err = None
            for _ in range(tries):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    last_err = e
            raise last_err
        return wrapper
    return decorator

